<script setup>
import AdminFilterSummary from '../../components/admin/AdminFilterSummary.vue'
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import AppSkeleton from "../../components/common/AppSkeleton.vue"
import AdminIcon from '../../components/admin/AdminIcon.vue'
import AdminFilterExtras from '../../components/admin/AdminFilterExtras.vue'
import {reactive,watch} from 'vue'
import {RouterLink} from 'vue-router'
import {paymentsApi} from '../../api/payments.api'
import {useOrderPolling} from '../../composables/useOrderPolling'
import {useAuthStore} from '../../stores/auth'
import {paymentStatusLabels,paymentMethodLabels,paymentAmount,getPaymentMethodLabel} from '../../utils/paymentStatus'
import {formatDateTime} from '../../utils/formatters'
import PaymentStatusBadge from '../../components/payments/PaymentStatusBadge.vue'
import ApiPagination from '../../components/admin/catalog/ApiPagination.vue'
const auth=useAuthStore(),filters=reactive({search:'',status:'',method:'',provider:'',order_number:'',date_from:'',date_to:'',sort:'created_at',direction:'desc'})
const filterDefaults={...filters}
let applied={...filters},page=1
const state=useOrderPolling(signal=>paymentsApi.list({...applied,page,per_page:15},signal),{interval:20000,enabled:()=>auth.can('payments.view')})
const {data,loading,refreshing,error,syncedAt}=state
function load(next=1){if(next===1)applied={...filters};page=next;state.reset();void state.load()}
watch(()=>auth.token,()=>{state.reset();if(auth.can('payments.view'))void state.load()},{immediate:true})
</script>
<template><main id="main"><AdminPageHeader class="page-heading"><div><span class="eyebrow">إدارة شيشلي</span><h1>المدفوعات</h1><p>محاولات الدفع المسجلة لدى المطعم، وحالتها مستقلة عن حالة الطلب.</p></div><button class="button" :disabled="refreshing" @click="state.load(true)"><AdminIcon name="refresh"/> تحديث المدفوعات</button></AdminPageHeader><section class="panel payments-panel"><form class="admin-list-filters" @submit.prevent="load()"><div class="admin-filter-primary"><label class="field">بحث برقم الطلب أو مرجع المزود<input v-model="filters.search" name="payment_search" maxlength="150" type="search"></label><label class="field">حالة الدفع<select v-model="filters.status" name="payment_status"><option value="">كل الحالات</option><option v-for="(label,value) in paymentStatusLabels" :value="value" :key="value">{{ label }}</option></select></label><label class="field">طريقة الدفع<select v-model="filters.method" name="payment_method"><option value="">كل الطرق المسجلة</option><option v-for="(label,value) in paymentMethodLabels" :value="value" :key="value">{{ label }}</option></select></label><button class="button" :disabled="refreshing"><AdminIcon name="search"/> تطبيق الفلاتر</button></div><AdminFilterExtras :errors="error?.errors"><label class="field">مزود الدفع<input v-model="filters.provider" name="payment_provider" maxlength="50" placeholder="الاسم المسجل إن وجد"></label><label class="field">رقم الطلب المطابق<input v-model="filters.order_number" name="payment_order" maxlength="255"></label><label class="field">من تاريخ<input v-model="filters.date_from" name="date_from" type="date"></label><label class="field">إلى تاريخ<input v-model="filters.date_to" name="date_to" type="date"></label><label class="field">الترتيب<select v-model="filters.sort" name="payment_sort"><option value="created_at">وقت الإنشاء</option><option value="amount">المبلغ</option><option value="status">الحالة</option><option value="method">الطريقة</option></select></label><label class="field">الاتجاه<select v-model="filters.direction" name="direction"><option value="desc">تنازلي</option><option value="asc">تصاعدي</option></select></label></AdminFilterExtras></form><AdminFilterSummary :filters="filters" :defaults="filterDefaults" :busy="refreshing" @clear="Object.assign(filters,filterDefaults);load()"/><p v-if="syncedAt">آخر مزامنة: {{ formatDateTime(syncedAt) }}</p><AppSkeleton v-if="refreshing&&!loading" variant="inline" label="جارٍ تحديث البيانات…"/><AppSkeleton v-if="loading" variant="table" label="جارٍ تحميل المدفوعات…"/><div v-if="error" role="alert"><p>{{ error.message }}</p><p v-for="(messages,key) in error.errors" :key="key">{{ messages.join(' ') }}</p><p v-if="data">تظهر آخر بيانات مؤكدة؛ تعذرت المزامنة الحالية.</p><button class="button" :disabled="refreshing" @click="state.load()">إعادة المحاولة</button></div><div v-if="data?.data.length" class="table-wrap"><table v-admin-table class="payments-table"><thead><tr><th>الطلب</th><th>طريقة الدفع</th><th>المبلغ</th><th>الحالة</th><th>وقت الإنشاء</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="payment in data.data" :key="payment.id"><td><div class="admin-cell-value"><strong dir="ltr">{{ payment.order?.order_number||'محاولة دفع' }}</strong></div></td><td><div class="admin-cell-value">{{ getPaymentMethodLabel(payment.method) }}<small class="product-description">{{ payment.provider||'دفع عند الاستلام' }}</small></div></td><td><div class="admin-cell-value"><strong>{{ paymentAmount(payment.amount,payment.currency) }}</strong></div></td><td><div class="admin-cell-value"><PaymentStatusBadge :status="payment.status"/></div></td><td><div class="admin-cell-value">{{ formatDateTime(payment.created_at) }}</div></td><td><div class="admin-cell-value"><div class="catalog-actions"><RouterLink class="row-button" :to="'/admin/payments/'+payment.id">تفاصيل الدفع <AdminIcon name="arrow-left"/></RouterLink><RouterLink v-if="auth.can('orders.view')&&payment.order" class="row-button" :to="'/admin/orders/'+payment.order.id">الطلب المرتبط</RouterLink></div></div></td></tr></tbody></table></div><p v-if="data&&!data.data.length" class="empty">لا توجد مدفوعات تطابق البحث.</p><ApiPagination v-if="data" :meta="data.meta" :links="data.links" :busy="refreshing" @page="load"/></section></main></template>

